<template>
  <div class="Json">
    <div class="json-head-bar">
      <div class="json-head-actions">
        <div class="json-head-btn json-btn-primary" @click="jsonFormat">
          <svg class="json-btn-icon" viewBox="0 0 24 24" aria-hidden="true">
            <path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
              d="M4 6h6m-6 6h10m-10 6h4M18 6v12m0 0-3-3m3 3 3-3" />
          </svg>
          <span>格式化</span>
        </div>
        <div class="json-head-btn" @click="jsonStringify">
          <svg class="json-btn-icon" viewBox="0 0 24 24" aria-hidden="true">
            <path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
              d="M4 12h16M8 7l4 5-4 5m8-10 4 5-4 5" />
          </svg>
          <span>压缩</span>
        </div>
      </div>

      <div class="json-head-title">
        <span class="json-head-badge">{{ jsonLength }} 字符</span>
      </div>

      <div class="json-head-actions json-head-actions-right">
        <div class="json-head-btn" @click="copyJson">
          <svg class="json-btn-icon" viewBox="0 0 24 24" aria-hidden="true">
            <path fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"
              d="M9 9V5a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2h-4M5 9h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2z" />
          </svg>
          <span>{{ ok ? '已复制' : '复制' }}</span>
        </div>
        <div class="json-head-btn json-btn-danger" @click="clearJson">
          <svg class="json-btn-icon" viewBox="0 0 24 24" aria-hidden="true">
            <path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
              d="M4 7h16M10 4h4M6 7l1 13h10l1-13M10 11v6m4-6v6" />
          </svg>
          <span>清空</span>
        </div>
      </div>
    </div>

    <div class="json-text-area">
      <div class="json-editor-shell">
        <textarea v-model="jsonVal" spellcheck="false"
          placeholder='在此输入json字符串，例如：{"name":"Archer","tags":["Vue","Node"]}'></textarea>
        <div class="json-editor-tip">
          <span>格式化：美化缩进 4 空格</span>
          <span>压缩：移除全部空白</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
  import {beautifyJsonString, jsonSimplify} from '@/util/json'
  export default {
    components: {},
    data(){
      return {
        ok: false,
        jsonVal: "",
        jsonResults: [],
        btnHover: false
      }
    },
    computed: {
      jsonLength() {
        return this.jsonVal ? this.jsonVal.length : 0;
      }
    },
    mounted(){
    },
    methods: {
      jsonFormat() {
        if(this.jsonVal !== '') {
          this.jsonResults = beautifyJsonString(this.jsonVal);
          this.jsonVal = this.jsonResults.join("\n");
        }
      },
      jsonStringify() {
        this.jsonFormat();
        this.jsonVal = jsonSimplify(this.jsonResults);
        this.jsonResults = [];
      },
      copyJson() {
        if(this.jsonVal === '') {
          return;
        }
        let self = this;
        let textarea = document.createElement('textarea');
        textarea.value = this.jsonVal;
        document.body.appendChild(textarea);
        textarea.select();
        try {
          document.execCommand('copy');
          self.ok = true;
          setTimeout(() => {
            self.ok = false;
          }, 1500);
        } catch (e) {
          self.ok = false;
        }
        document.body.removeChild(textarea);
      },
      clearJson() {
        this.jsonVal = "";
        this.jsonResults = [];
      }
    }
  }
</script>

