
/**
 * 将可能由多个 JSON 片段拼接的字符串分割成数组
 * 使用栈和字符串状态来识别顶层完整的 JSON 对象或数组
 * @param {string} str - 原始字符串
 * @returns {string[]} JSON 片段数组
 */
function splitJsonParts(str) {
    let parts = [];
    let stack = 0;          // 括号栈深度
    let start = 0;          // 当前片段起始位置
    let inString = false;   // 是否在字符串内部
    let escape = false;     // 是否转义字符

    for (let i = 0; i < str.length; i++) {
        let ch = str[i];

        if (inString) {
            // 处理字符串内部的转义和结束引号
            if (escape) {
                escape = false;
            } else if (ch === '\\') {
                escape = true;
            } else if (ch === '"') {
                inString = false;
            }
        } else {
            if (ch === '"') {
                inString = true;
            } else if (ch === '{' || ch === '[') {
                stack++;
            } else if (ch === '}' || ch === ']') {
                stack--;
                if (stack === 0) {
                    // 栈归零，找到一个完整片段
                    let part = str.substring(start, i + 1);
                    parts.push(part);
                    start = i + 1;
                }
            }
        }
    }

    // 处理剩余未闭合的部分（例如缺少结束括号）
    if (start < str.length) {
        parts.push(str.substring(start));
    }

    return parts;
}

/**
 * 尝试补全缺失的括号并美化
 * @param {string} str - 可能不完整的 JSON 字符串
 * @returns {string} 美化后的字符串，若仍失败则返回原字符串
 */
function tryFixAndPretty(str) {
    // 计算未闭合的括号
    let openBrackets = [];
    let inString = false;
    let escape = false;

    for (let i = 0; i < str.length; i++) {
        let ch = str[i];

        if (inString) {
            if (escape) {
                escape = false;
            } else if (ch === '\\') {
                escape = true;
            } else if (ch === '"') {
                inString = false;
            }
        } else {
            if (ch === '"') {
                inString = true;
            } else if (ch === '{' || ch === '[') {
                openBrackets.push(ch);
            } else if (ch === '}' || ch === ']') {
                if (openBrackets.length > 0) {
                    openBrackets.pop();
                }
            }
        }
    }

    // 在末尾补全缺失的闭合括号
    let fixed = str;
    for (let i = openBrackets.length - 1; i >= 0; i--) {
        let bracket = openBrackets[i];
        if (bracket === '{') {
            fixed += '}';
        } else if (bracket === '[') {
            fixed += ']';
        }
    }

    // 尝试解析补全后的字符串
    try {
        let parsed = JSON.parse(fixed);
        return {ok: true, part: JSON.stringify(parsed, null, 2)};
    } catch (e) {
        if(str.startsWith("[Invalid JSON] ")) {
            return str;
        }
        return `[Invalid JSON] ${str}`;
    }
}

/**
 * 美化展示 JSON 字符串，支持以下场景：
 * - 标准 JSON 对象/数组
 * - 多个 JSON 串直接拼接（如 {"a":1}{"b":2}）
 * - 缺少开头或结尾括号的 JSON（如 {"a":1 或 "a":1}）
 * @param {string} input - 原始 JSON 字符串
 * @returns {string[]} 美化后的字符串
 */
function beautifyJsonString(input) {
    if (typeof input !== 'string') {
        throw new Error('Input must be a string');
    }

    // 1. 尝试直接解析整个字符串
    try {
        let parsed = JSON.parse(input);
        return [JSON.stringify(parsed, null, 2)];
    } catch (e) {
        // 2. 直接解析失败，尝试分割多个 JSON 片段
        let parts = splitJsonParts(input);
        if (parts.length > 1) {
            // 多个片段分别美化，用分隔线连接
            let prettyParts = parts.map(part => {
                try {
                    let parsed = JSON.parse(part);
                    return JSON.stringify(parsed, null, 2);
                } catch (err) {
                    return tryFixAndPretty(part);
                }
            });
            return prettyParts
        } else {
            // 单个片段，尝试补全括号
            return [tryFixAndPretty(input)];
        }
    }
}

function jsonSimplify(jsonResults) {
    let jsonVal = "";
    if(jsonResults.length > 0) {
        for(let o of jsonResults) {
            let p = o.replace('[Invalid JSON] ', '')
            try {
                jsonVal += JSON.stringify(JSON.parse(p));
            }catch(e) {
                jsonVal += p;
            }
        }
    }
    return jsonVal;
}

module.exports = {
    beautifyJsonString: beautifyJsonString,
    jsonSimplify: jsonSimplify
}