<template>
  <div class="MdEditor">
    <div class="md-editor-body">
      <Editor
        class="bytemd"
        ref="editor"
        :mode="mode"
        :value="value"
        :plugins="plugins"
        @change="handleChange"
      />
    </div>
  </div>
</template>

<script>
import "bytemd/dist/index.min.css";
import { Editor } from "@bytemd/vue";
import codeCopy from '@/util/mdcopypl'

const plugins = [
  codeCopy()
];

export default {
  name: "MdEditor",
  components: { Editor },
  data() {
    let md = localStorage.getItem("markdown-text");
    if(!md) {
      md = `# 在此处编辑`
    }
    return {
      mode: "auto",
      value: md,
      plugins: plugins,
    };
  },
  mounted() {
  },
  methods: {
    handleChange(v) {
      this.value = v;
      this.saveMarkdown(v);
    },
    onEditorFocus() {
      this.saveMarkdown();
    },
    onEditorBlur() {
      this.saveMarkdown();
    },
    onEditorChange() {
      this.saveMarkdown();
    },
    onEditorStateChange() {
      this.saveMarkdown();
    },
    setValue(val) {
      return this.$refs.editor.value = val;
    },
    getValue() {
      return this.$refs.editor.value;
    },
    saveMarkdown(val) {
      let v = val ? val : this.getValue();
      localStorage.setItem("markdown-text", v);
    }
  },
};
</script>

