            <div class="size-label">转换大小:</div>
            <div class="size-bar">
              <div class="size-fill size-fill-converted" :style="{ width: convertedRate + '%' }"></div>
            </div>
            <span class="size-value">{{ formatFileSize(convertedSize) }}</span>
          </div>
        </div>

        <button class="image-select-btn image-select-btn-download" v-if="convertedImage" @click="downloadImage">
          <svg class="download-icon" viewBox="0 0 24 24" aria-hidden="true">
            <path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"
