<template>
    <div class="carousel-wrapper">
        <div class="carousel"
             @mouseenter="handleMouseEnter"
             @mouseleave="handleMouseLeave"
             @touchstart="handleMouseEnter"
             @touchend="handleMouseLeave">
            <div class="slides-container">
                <div v-for="(item, idx) in images" 
                     :key="idx" 
                     class="carousel-slide"
                     :style="{ opacity: currentIndex === idx ? 1 : 0 }"
                     @click="openImg()"
                     >
                    <img :src="item.url" :alt="item.alt || '轮播图片'">
                </div>
            </div>
            <div class="carousel-arrow arrow-left" @click="prevSlide" title="上一张">
                <div class="arrow-icon">‹</div>
            </div>
            <div class="carousel-arrow arrow-right" @click="nextSlide" title="下一张">
                <div class="arrow-icon">›</div>
            </div>
            <div class="carousel-dots">
                <div v-for="(item, idx) in images"
                     :key="'dot-'+idx"
                     class="dot"
                     :class="{ active: currentIndex === idx }"
                     @click="goToSlide(idx)">
                </div>
            </div>
            <div class="carousel-caption">
                <span class="caption-index">{{ currentIndex+1 }} / {{ images.length }}</span>
                <span class="caption-divider"></span>
                <span class="caption-title">{{ currentTitle }}</span>
                <span class="caption-zoom">
                    <svg viewBox="0 0 24 24" aria-hidden="true">
                        <path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
                          d="M11 4a7 7 0 1 1 0 14 7 7 0 0 1 0-14zm5.5 12L20 19.5M11 8v6m-3-3h6" />
                    </svg>
                </span>
            </div>
            <div class="carousel-progress">
                <div class="carousel-progress-bar" :style="{ width: progressWidth }"></div>
            </div>
        </div>
    </div>
</template>
<script>
export default  {
    name: "ImageView",
    data() {
        let {imgShow, imgMask, img} = this.createEl();

        return {
            images: [
                {
                    url: require('@/assets/image/md.png'), 
                    alt: 'Markdown实时编辑',
                    title: 'markdown实时编辑'
                },
                {
                    url: require('@/assets/image/bg.png'),
                    alt: '智能抠图',
                    title: '智能抠图'
                },
                {
                    url: require('@/assets/image/api.png'), 
                    alt: 'API测试',
                    title: 'API测试'
                },
                {
                    url: require('@/assets/image/abg.png'), 
                    alt: 'Agent修图',
                    title: 'Agent修图'
                },
                {
                    url: require('@/assets/image/doc.png'), 
                    alt: 'Agent文档',
                    title: 'Agent文档'
                }
            ],
            currentIndex: 0,      
            autoTimer: null,     
            autoPlayDelay: 3000,
            showImg: false,
            currentImageUrl: '',
            imgMask: imgMask,
            imgShow: imgShow,
            img: img
        }
    },
    computed: {
        currentTitle() {
            let cur = this.images[this.currentIndex];
            return cur ? cur.title : '';
        },
        progressWidth() {
            let len = this.images.length;
            return len ? (((this.currentIndex + 1) / len) * 100).toFixed(2) + '%' : '0%';
        }
    },
    mounted() {
        this.startAutoPlay();
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    },
    beforeDestroy() {
        this.stopAutoPlay();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    },
    methods: {
        createEl() {
            let imgShow = document.createElement('div');
            imgShow.classList.add('image-view-container');
            imgShow.id = "image-view-container"
            let button = document.createElement('button');
            button.classList.add('image-view-close-btn');
            button.onclick = this.closeImg;
            button.innerHTML = '&times;';
            let img = document.createElement('img');
            img.classList.add('image-view-model');
            img.alt = '大图预览';

            imgShow.appendChild(button);
            imgShow.appendChild(img);
            
            let imgMask = document.createElement('div');
            imgMask.id = "image-view-mask"
            imgMask.style.height = window.innerHeight + "px",
            imgMask.style.width = window.innerWidth + "px";
            imgMask.style.backgroundColor = "black"
            imgMask.style.opacity = 0.1;
            imgMask.style.position = 'fixed';
            imgMask.style.top = 0;
            imgMask.style.left = 0;
            imgMask.onclick = this.closeImg;

            return {imgShow, imgMask, img};
        },
        nextSlide() {
            const len = this.images.length;
            let nextIndex = this.currentIndex + 1;
            if (nextIndex >= len) {
                nextIndex = 0;
            }
            this.setCurrentIndex(nextIndex);
            this.resetAutoPlay();
        },
        prevSlide() {
            const len = this.images.length;
            let prevIndex = this.currentIndex - 1;
            if (prevIndex < 0) {
                prevIndex = len - 1;
            }
            this.setCurrentIndex(prevIndex);
            this.resetAutoPlay();
        },
        goToSlide(index) {
            if (index === this.currentIndex) return;
            if (index >= 0 && index < this.images.length) {
                this.setCurrentIndex(index);
                this.resetAutoPlay();
            }
        },
        setCurrentIndex(newIndex) {
            if (newIndex === this.currentIndex) return;
            this.currentIndex = newIndex;
        },
        startAutoPlay() {
            if (this.autoTimer) return; 
            this.autoTimer = setInterval(() => {
                this.nextSlide();
            }, this.autoPlayDelay);
        },
        stopAutoPlay() {
            if (this.autoTimer) {
                clearInterval(this.autoTimer);
                this.autoTimer = null;
            }
        },
        resetAutoPlay() {
            this.stopAutoPlay();
            this.startAutoPlay();
        },
        handleMouseEnter() {
            this.stopAutoPlay();
        },
        handleMouseLeave() {
            if (!this.autoTimer) {
                this.startAutoPlay();
            }
        },
        handleVisibilityChange() {
            if (document.hidden) {
                this.stopAutoPlay();
            } else {
                if (!this.autoTimer) {
                    this.startAutoPlay();
                }
            }
        },
        openImg() {
            this.currentImageUrl = this.images[this.currentIndex].url;
            if(this.showImg) {
                return ;
            }
            this.imgMask.style.height = window.innerHeight + "px",
            this.imgMask.style.width = window.innerWidth + "px";
            this.imgShow.style.height = "500px",
            this.imgShow.style.width = "800px";
            this.img.src = this.currentImageUrl;
            let imgMask = document.getElementById('image-view-mask');
            if(!imgMask) {
                document.body.appendChild(this.imgMask);
            }
            let imgShow = document.getElementById('image-view-container');
            if(!imgShow) {
                document.body.appendChild(this.imgShow);
            }
            this.showImg = true;
        },
        closeImg() {
            if (!this.showImg) return;
            
            this.showImg = false;
            this.currentImageUrl = '';
            document.body.removeChild(this.imgMask);
            document.body.removeChild(this.imgShow);
        }
    }
}
</script>
